{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.4.1.json",
  "config": {
    "view": {
      "continuousHeight": 300,
      "continuousWidth": 300
    }
  },
  "encoding": {
    "tooltip": [
      {
        "field": "event_year",
        "type": "ordinal"
      },
      {
        "field": "event_count",
        "type": "quantitative"
      }
    ],
    "x": {
      "field": "event_year",
      "title": "Year",
      "type": "ordinal"
    },
    "y": {
      "field": "event_count",
      "title": "Number of Event Permits",
      "type": "quantitative"
    }
  },
  "height": 400,
  "mark": {
    "color": "#2c7fb8",
    "type": "bar"
  },
  "title": "Chicago Park District Outdoor Event Permits by Year",
  "width": 600
}
